<script>
(() => { const root = document.getElementById('criteria'); let next = root.querySelectorAll('.criterion').length; document.getElementById('add-criterion').addEventListener('click', () => { const i = next++; const el = document.createElement('div'); el.className = 'border rounded p-3 criterion'; el.innerHTML = `<div class="row g-2"><div class="col-md-4"><label class="form-label">Nama</label><input name="criteria[${i}][nama]" maxlength="150" class="form-control" required></div><div class="col-md-3"><label class="form-label">Bobot %</label><input name="criteria[${i}][bobot]" type="number" step="0.01" min="0.01" max="100" class="form-control" required></div><div class="col-md-3"><label class="form-label">Skor maksimum</label><input name="criteria[${i}][skor_maksimum]" type="number" step="0.01" min="0.01" class="form-control" required></div><div class="col-md-2 d-flex align-items-end"><button type="button" class="btn btn-outline-danger remove-criterion">Hapus</button></div><div class="col-12"><label class="form-label">Indikator</label><textarea name="criteria[${i}][deskripsi]" rows="2" class="form-control"></textarea></div></div>`; root.append(el); }); root.addEventListener('click', (e) => { if (e.target.classList.contains('remove-criterion')) e.target.closest('.criterion').remove(); }); })();
</script>
